def blockScalarMatrix (h : FewOperators 𝕜 X ι)
    (T : DependentCZeroSum 𝕜 X →L[𝕜] DependentCZeroSum 𝕜 X) (s t : P) : 𝕜 :=
  if hts : t ≤ s then fewOperatorCoefficient h hts (operatorBlock 𝕜 X X T s t) else 0

